<?php
declare(strict_types=1);
require_once __DIR__ . '/../middleware/role-check.php';require_once __DIR__ . '/../config/database.php';require_once __DIR__ . '/../helpers/notify.php';header('Content-Type: application/json; charset=utf-8');requireMarketplaceRole();$uid=(int)getAuthenticatedUserId();
if($_SERVER['REQUEST_METHOD']==='POST'){$d=json_decode((string)file_get_contents('php://input'),true);$id=is_array($d)?filter_var($d['listing_id']??null,FILTER_VALIDATE_INT):false;if(!$id||$id<1){http_response_code(422);echo json_encode(['success'=>false,'message'=>'A valid listing is required.']);exit;}$s=$pdo->prepare("UPDATE resale_listings SET status='withdrawn' WHERE id=:id AND seller_id=:seller AND status='active'");$s->execute([':id'=>$id,':seller'=>$uid]);if(!$s->rowCount()){http_response_code(404);echo json_encode(['success'=>false,'message'=>'Active listing not found.']);exit;}$message=sprintf('Your resale listing #%d was withdrawn.',(int)$id);createNotification($pdo,$uid,'Resale listing withdrawn',$message,'info');notifyAdminsOfActivity($pdo,$uid,'Resale listing withdrawn',$message,'info');echo json_encode(['success'=>true,'message'=>'Listing withdrawn.']);exit;}
if($_SERVER['REQUEST_METHOD']!=='GET'){http_response_code(405);echo json_encode(['success'=>false,'message'=>'Method not allowed.']);exit;}$s=$pdo->prepare('SELECT l.id,l.asking_price,l.condition_grade,l.condition_description,l.defects,l.status,l.reservation_order_id,l.created_at,l.sold_at,e.name,i.assigned_at FROM resale_listings l JOIN inventory i ON i.id=l.inventory_id JOIN equipment e ON e.id=i.equipment_id WHERE l.seller_id=:seller ORDER BY l.created_at DESC');$s->execute([':seller'=>$uid]);echo json_encode(['success'=>true,'listings'=>$s->fetchAll(PDO::FETCH_ASSOC)]);
